<?php
require_once 'config/config.php';require_once 'includes/functions.php';require_login();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$old=$_POST['old_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$s=$pdo->prepare('SELECT password_hash FROM admins WHERE id=?');$s->execute([$_SESSION['admin_id']]);$hash=$s->fetchColumn();
if(!password_verify($old,$hash))$error='Current password is incorrect.';elseif(strlen($new)<8)$error='New password must be at least 8 characters.';elseif($new!==$confirm)$error='New passwords do not match.';else{$pdo->prepare('UPDATE admins SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);flash('Password updated successfully.');redirect('index.php');}}
$page_title='Change Password';require 'includes/header.php';?>
<section class="panel narrow"><h1>Change password</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Current password</label><input type="password" name="old_password" required></div><div class="field"><label>New password</label><input type="password" name="new_password" minlength="8" required></div><div class="field"><label>Confirm new password</label><input type="password" name="confirm_password" minlength="8" required></div><button class="btn primary">Update password</button></form></section><?php require 'includes/footer.php';?>
